package com.example.demo.request;

import com.example.demo.notification.*;import com.example.demo.user.User;
import jakarta.persistence.OptimisticLockException;import jakarta.transaction.Transactional;
import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;
import java.util.*;

@Service
public class RequestWorkflowService {
 private final MaintenanceRequestRepository requests;private final RequestHistoryRepository history;private final NotificationRepository notifications;
 public RequestWorkflowService(MaintenanceRequestRepository r,RequestHistoryRepository h,NotificationRepository n){requests=r;history=h;notifications=n;}
 public MaintenanceRequest requireVisible(Long id,User actor){MaintenanceRequest r=requests.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Request not found."));boolean ok=actor.getRole()==User.Role.ADMIN||(actor.getRole()==User.Role.STUDENT&&r.getUser().getId().equals(actor.getId()))||(actor.getRole()==User.Role.STAFF&&r.getAssignee()!=null&&r.getAssignee().getId().equals(actor.getId()));if(!ok)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You cannot access this request.");return r;}
 @Transactional public MaintenanceRequest assign(Long id,User admin,User staff,MaintenanceRequest.Priority priority){admin(admin);MaintenanceRequest r=requests.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(r.getStatus()==MaintenanceRequest.Status.COMPLETED)bad("Completed requests cannot be reassigned.");User old=r.getAssignee();r.setAssignee(staff);if(priority!=null)r.setPriority(priority);history.save(new RequestHistory(r,admin,"ASSIGNMENT_CHANGED",old==null?(staff==null?"Left unassigned":"Assigned to "+staff.getFullName()):(staff==null?"Unassigned from "+old.getFullName():"Reassigned from "+old.getFullName()+" to "+staff.getFullName())));if(staff!=null)notifications.save(new Notification(staff,"Request #"+r.getId()+" was assigned to you.",r.getId()));notifications.save(new Notification(r.getUser(),staff==null?"Request #"+r.getId()+" was unassigned.":"Request #"+r.getId()+" was assigned to "+staff.getFullName()+".",r.getId()));return requests.save(r);}
 @Transactional public MaintenanceRequest start(Long id,User staff){staff(staff);MaintenanceRequest r=requireVisible(id,staff);if(r.getStatus()!=MaintenanceRequest.Status.PENDING)bad("Only pending requests can be started.");r.start();history.save(new RequestHistory(r,staff,"WORK_STARTED","Status changed from PENDING to IN_PROGRESS"));notifications.save(new Notification(r.getUser(),"Work started on request #"+r.getId()+".",r.getId()));return requests.save(r);}
 @Transactional public MaintenanceRequest complete(Long id,User staff,String note){staff(staff);if(note==null||note.isBlank())bad("A repair note is required.");MaintenanceRequest r=requireVisible(id,staff);if(r.getStatus()!=MaintenanceRequest.Status.IN_PROGRESS)bad("Only in-progress requests can be completed.");r.complete(note.trim());history.save(new RequestHistory(r,staff,"WORK_COMPLETED","Completed with repair note: "+note.trim()));notifications.save(new Notification(r.getUser(),"Request #"+r.getId()+" was completed.",r.getId()));return requests.save(r);}
 public List<RequestHistory> history(Long id){return history.findByRequestIdOrderByCreatedAtAsc(id);}private void admin(User u){if(u.getRole()!=User.Role.ADMIN)forbidden();}private void staff(User u){if(u.getRole()!=User.Role.STAFF||u.isMustChangePassword())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Change your temporary password before using staff features.");}private void forbidden(){throw new ResponseStatusException(HttpStatus.FORBIDDEN);}private void bad(String m){throw new ResponseStatusException(HttpStatus.CONFLICT,m);}
}
